import{_ as a,c as n,o as t,ae as o}from"./chunks/framework.Cd-3tpCq.js";const m=JSON.parse('{"title":"Channel","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/channels/index.md","filePath":"api/rest-api/shop/channels/index.md"}'),s={name:"api/rest-api/shop/channels/index.md"};function r(h,e,i,c,l,d){return t(),n("div",null,e[0]||(e[0]=[o('<h1 id="channel" tabindex="-1">Channel <a class="header-anchor" href="#channel" aria-label="Permalink to &quot;Channel&quot;">​</a></h1><p>The Channel menu describes the storefronts (channels) the store publishes — each with its own code, hostname, theme, default locale and currency. Use it to learn which channel a client is operating against and to render channel-specific labels and content.</p><h2 id="channels-and-translations" tabindex="-1">Channels and Translations <a class="header-anchor" href="#channels-and-translations" aria-label="Permalink to &quot;Channels and Translations&quot;">​</a></h2><ul><li><strong>Channels</strong> return the configured storefronts and their settings — code, hostname, theme, maintenance flag, and the enabled locales and currencies.</li><li><strong>Channel translations</strong> hold a channel&#39;s localised text: its name, description, home and footer content, and the maintenance-mode message.</li></ul><h2 id="the-channel-object-carries-no-name" tabindex="-1">The Channel Object Carries No Name <a class="header-anchor" href="#the-channel-object-carries-no-name" aria-label="Permalink to &quot;The Channel Object Carries No Name&quot;">​</a></h2><p>A channel&#39;s display name lives in its translation, not on the channel itself. Both <code>translation</code> (the request locale) and <code>translations</code> (all locales) come back as <strong>path references</strong>, so rendering a channel switcher means following <code>translation</code> for each channel. The same applies to <code>locales</code>, <code>currencies</code>, <code>defaultLocale</code>, and <code>baseCurrency</code> — all references rather than nested objects.</p><p>The SEO block is the exception: <code>homeSeo</code> is returned inline as an object of <code>meta_title</code>, <code>meta_keywords</code>, and <code>meta_description</code>, so a home-page <code>&lt;head&gt;</code> can be built from the channel row alone.</p><h2 id="what-the-code-is-for" tabindex="-1">What the <code>code</code> Is For <a class="header-anchor" href="#what-the-code-is-for" aria-label="Permalink to &quot;What the `code` Is For&quot;">​</a></h2><p><code>code</code> is the value every other endpoint expects in the <code>X-Channel</code> header — the numeric <code>id</code> is not accepted there. Channel scope decides which products, categories, and prices a request sees, and the wishlist is stored per channel, so a shopper&#39;s saved items differ between storefronts.</p><h2 id="maintenance-mode" tabindex="-1">Maintenance Mode <a class="header-anchor" href="#maintenance-mode" aria-label="Permalink to &quot;Maintenance Mode&quot;">​</a></h2><p><code>isMaintenanceOn</code> tells a client the storefront is closed; <code>allowedIps</code> lists any addresses still let through. The message to show comes from the channel&#39;s translation, so read that before rendering a maintenance screen.</p><h2 id="timestamps-may-be-null" tabindex="-1">Timestamps May Be Null <a class="header-anchor" href="#timestamps-may-be-null" aria-label="Permalink to &quot;Timestamps May Be Null&quot;">​</a></h2><p>Channels installed with the store return <code>null</code> for <code>createdAt</code> and <code>updatedAt</code>. Treat those as absent rather than as an error.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/channels/get-channels.html">Channels</a></td><td><code>GET /api/shop/channels</code></td><td>List the store&#39;s channels.</td></tr><tr><td><a href="/api/rest-api/shop/channels/get-channel-translations.html">Channel Translations</a></td><td><code>GET /api/shop/channel_translations</code></td><td>Localised content for a channel.</td></tr></tbody></table><p>All Channel endpoints are public reads that require only the storefront key — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',16)]))}const u=a(s,[["render",r]]);export{m as __pageData,u as default};
